# Generated by AI, edited by humans
import datetime
import json
import os
from Region import REGIONS
from cloudflare import CloudflareR2
from system_utils import mkpath, PATH

CACHE_FILE_PATH = mkpath(PATH.WEBSITE, 'cache/avg_image_size_cache.json')


def read_cached_average_size() -> float | None:
    try:
        if os.path.isfile(CACHE_FILE_PATH):
            with open(CACHE_FILE_PATH, 'r', encoding='utf-8') as f:
                data = json.load(f)
                val = data.get('avg_image_size_bytes')
                if val and isinstance(val, (int, float)) and val > 0:
                    return float(val)
    except Exception:
        pass
    return None


def write_cached_average_size(size_bytes: float) -> None:
    try:
        os.makedirs(os.path.dirname(CACHE_FILE_PATH), exist_ok=True)
        with open(CACHE_FILE_PATH, 'w', encoding='utf-8') as f:
            json.dump({
                'avg_image_size_bytes': size_bytes,
                'updated_at': datetime.datetime.now(datetime.timezone.utc).isoformat()
            }, f, indent=2)
    except Exception as err:
        print(f'Warning: failed to write image size cache: {err}')


def calculate_average_image_size(
    storage: CloudflareR2 | None = None,
    *,
    use_cache_only: bool = False
) -> float:
    if use_cache_only:
        cached = read_cached_average_size()
        if cached is not None:
            return cached
        raise RuntimeError(f'Cache file not found or empty: {CACHE_FILE_PATH}. Run a full build first.')

    if storage is None:
        storage = CloudflareR2()

    current_year = datetime.date.today().year
    years_to_check = [current_year, current_year - 1]

    total_image_size = 0
    image_count = 0

    for region in REGIONS:
        for year in years_to_check:
            prefix = f'{region.api_country}/{region.api_lang}/{year}-'
            try:
                size, count = storage.get_stats(prefix)
                total_image_size += size
                image_count += count
            except Exception as err:
                print(f'Warning: failed to get stats for prefix {prefix}: {err}')

    if image_count == 0:
        usage = storage.get_bucket_usage()
        total_image_size, image_count = usage or (0, 0)

    if image_count > 0:
        avg_size = total_image_size / image_count
        write_cached_average_size(avg_size)
        return avg_size

    cached = read_cached_average_size()
    if cached is not None:
        return cached

    raise RuntimeError('Failed to calculate average image size from Cloudflare R2 and no cached size is available.')
